#!/usr/bin/env python3
"""Metadata-only contract export of completed, immutable supplemental results."""
import hashlib,json
from pathlib import Path
import pandas as pd
ROOT=Path(__file__).resolve().parents[1];BASE=ROOT/'experiments/runs/v2/resource_cap_confirmation'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 lock=json.loads((BASE/'selection_lock.json').read_text());complete=json.loads((BASE/'complete.json').read_text());assert complete['complete'];reg=json.loads((ROOT/'experiments/experiment_config/configs/campaign.json').read_text())['model_registry'];states={c['system_id']:c['candidate'] for c in lock['choices'] if c['system_id']};raw=pd.read_parquet(BASE/'item_predictions_losses.parquet');choices=pd.read_csv(BASE/'coverage_and_cap_compliance.csv');out=BASE/'contract';out.mkdir(exist_ok=True)
 fixed={'protocol_id':'replacement_v2_second_untouched_resource_cap_confirmation','data_role':'second_unused_external_academic_population','task_id':'academic_mcq4','seed':81724051,'selected_before_test':True,'resource_cap_scope':'mean_coordinate_return_wall_latency_ms AND observed_peak_allocated_GPU_bytes; research_design_caps; finalclaims additionally require probabilityendpoint/globalguards','no_new_selection_in_this_export':True}
 for k,v in fixed.items():raw[k]=v;choices[k]=v
 raw['target_id']=raw.target_index.map(lambda i:reg[int(i)]['model_id']);raw['target_revision']=raw.target_index.map(lambda i:reg[int(i)]['revision']);raw['cluster_id']=raw.item_cluster;raw['TV']=raw.tv;raw['KL']=raw.kl;raw['actual_bits']=raw.system_id.map(lambda sid:states[sid]['actual_bits']);raw['adapter_family']=raw.system_id.map(lambda sid:states[sid]['family']);raw['peer_ids']=raw.system_id.map(lambda sid:json.dumps([reg[i]['model_id'] for i in states[sid]['pair']]));raw['peer_revisions']=raw.system_id.map(lambda sid:json.dumps([reg[i]['revision'] for i in states[sid]['pair']]))
 cols=['target_index','system_id','policy','cap_id','latency_cap_ms_per_context','allocated_VRAM_cap_bytes','final_measured_point_cap_compliant','final_latency_bound_and_observed_memory_compliant'];eligible=choices[choices.status=='eligible'][cols];perpolicy=raw.merge(eligible,on=['target_index','system_id'],how='inner',validate='many_to_many');perpolicy['budget']=perpolicy.cap_id;assert not perpolicy.duplicated(['target_index','policy','cap_id','item_id']).any();assert perpolicy.groupby(['target_index','policy','cap_id']).item_id.nunique().eq(complete['fresh_clusters']).all()
 raw.to_parquet(out/'per_state_query_losses.parquet',index=False);perpolicy.to_parquet(out/'per_policy_query_losses.parquet',index=False);choices.to_csv(out/'all_policy_cap_outcomes.csv',index=False)
 names=['per_state_query_losses.parquet','per_policy_query_losses.parquet','all_policy_cap_outcomes.csv'];(out/'manifest.json').write_text(json.dumps({'metadata_only_no_reselection':True,'source_complete_sha256':sha(BASE/'complete.json'),'source_code_sha256':sha(__file__),'source_loss_sha256':sha(BASE/'item_predictions_losses.parquet'),'source_cap_sha256':sha(BASE/'coverage_and_cap_compliance.csv'),'per_state_query_rows':len(raw),'per_policy_query_rows':len(perpolicy),'all_policy_cap_rows':len(choices),'expansion_is_not_more_independent_samples':True,'output_sha256':{n:sha(out/n) for n in names}},indent=2)+'\n');print('Exported',len(perpolicy),'policy/query rows retaining full cap outcomes')
if __name__=='__main__':main()
